import React, { useState, useEffect } from 'react';
import axios from 'axios';

function App() {
  const [resorts, setResorts] = useState([]);
  const [error, setError] = useState(null);

  useEffect(() => {
    async function fetchResorts() {
      try {
        const response = await axios.get(`${process.env.REACT_APP_API_URL}/ski-resorts`);
        setResorts(response.data);
      } catch (error) {
        setError('Error fetching resorts');
      }
    }

    fetchResorts();
  }, []);

  return (
    <div>
      <h1>Ski Resorts</h1>
      {error && <p>{error}</p>}
      <ul>
        {resorts && resorts.map((resort, index) => (
          <li key={index}>{resort.name}</li>
        ))}
      </ul>
    </div>
  );
}

export default App;
